import "sync"

// FanIn runs fn over every input concurrently and returns the results in the
// same order as the inputs. It currently deadlocks on any non-empty input.
func FanIn(inputs []int, workers int, fn func(int) int) []int {
	out := make([]int, len(inputs))
	jobs := make(chan int)
	var wg sync.WaitGroup

	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				out[i] = fn(inputs[i])
			}
		}()
	}

	for i := range inputs {
		jobs <- i
	}
	close(jobs)
	wg.Wait()
	return out
}

package cache

import "container/list"

type LRU struct {
	capacity int
	list     *list.List
	cache    map[string]*list.Element
}

type entry struct {
	key   string
	value int
}

func NewLRU(capacity int) *LRU {
	return &LRU{
		capacity: capacity,
		list:     list.New(),
		cache:    make(map[string]*list.Element),
	}
}

func (c *LRU) Get(key string) (int, bool) {
	if elem, ok := c.cache[key]; ok {
		c.list.MoveToFront(elem)
		return elem.Value.(*entry).value, true
	}
	return 0, false
}

func (c *LRU) Put(key string, value int) {
	if elem, ok := c.cache[key]; ok {
		elem.Value.(*entry).value = value
		c.list.MoveToFront(elem)
		return
	}

	newEntry := &entry{key: key, value: value}
	elem := c.list.PushFront(newEntry)
	c.cache[key] = elem

	if c.list.Len() > c.capacity {
		back := c.list.Back()
		delete(c.cache, back.Value.(*entry).key)
		c.list.Remove(back)
	}
}

func (c *LRU) Len() int {
	return c.list.Len()
}

